// Package conf 定义服务配置结构，由 configs/config.yaml 加载。
// 经典 kratos-layout 中该包由 protobuf 生成，这里用等价的手写结构体。
package conf

// Bootstrap 是配置的根结构。
type Bootstrap struct {
	Server *Server `json:"server"`
	Data   *Data   `json:"data"`
}

// Server 聚合各协议服务端配置。
type Server struct {
	HTTP *HTTPServer `json:"http"`
}

// HTTPServer 是 HTTP 服务端配置。Timeout 形如 "1s"、"500ms"。
type HTTPServer struct {
	Network string `json:"network"`
	Addr    string `json:"addr"`
	Timeout string `json:"timeout"`
}

// Data 聚合数据源配置。
type Data struct {
	Database *Database `json:"database"`
}

// Database 是数据源配置，当前实现为内存存储。
type Database struct {
	Driver string `json:"driver"`
	Source string `json:"source"`
}

// Package v1 定义 Greeter 服务的 API 消息。
// 经典 kratos-layout 中由 greeter.proto 生成，这里用等价的手写结构体。
package v1

// HelloRequest 是 SayHello 的请求。
type HelloRequest struct {
	Name string `json:"name"`
}

// HelloReply 是 SayHello 的响应。
type HelloReply struct {
	Message string `json:"message"`
}

// Package biz 是业务逻辑层，定义领域对象与仓储接口。
package biz

import "github.com/google/wire"

// ProviderSet 供 wire 装配本层依赖。
var ProviderSet = wire.NewSet(NewGreeterUsecase)

package biz

import (
	"context"

	"github.com/go-kratos/kratos/v2/log"
)

// Greeter 是领域对象。
type Greeter struct {
	Name    string
	Message string
}

// GreeterRepo 是仓储接口，由 data 层实现（依赖倒置）。
type GreeterRepo interface {
	Save(ctx context.Context, g *Greeter) (*Greeter, error)
}

// GreeterUsecase 是 Greeter 的业务用例。
type GreeterUsecase struct {
	repo GreeterRepo
	log  *log.Helper
}

// NewGreeterUsecase 创建业务用例。
func NewGreeterUsecase(repo GreeterRepo, logger log.Logger) *GreeterUsecase {
	return &GreeterUsecase{repo: repo, log: log.NewHelper(logger)}
}

// CreateGreeter 生成问候语并落库。
func (uc *GreeterUsecase) CreateGreeter(ctx context.Context, g *Greeter) (*Greeter, error) {
	uc.log.WithContext(ctx).Infof("CreateGreeter: %s", g.Name)
	g.Message = "Hello " + g.Name
	return uc.repo.Save(ctx, g)
}

// Package data 是数据访问层，实现 biz 定义的仓储接口。
package data

import (
	"sync"

	"hooo/internal/conf"

	"github.com/go-kratos/kratos/v2/log"
	"github.com/google/wire"
)

// ProviderSet 供 wire 装配本层依赖。
var ProviderSet = wire.NewSet(NewData, NewGreeterRepo)

// Data 持有共享的数据资源。经典布局中这里是 *gorm.DB / redis 客户端，
// 本示例用并发安全的内存存储代替。
type Data struct {
	mu       sync.RWMutex
	greeters map[string]string
}

// NewData 创建数据资源，返回清理函数供 kratos 优雅退出时调用。
func NewData(c *conf.Data, logger log.Logger) (*Data, func(), error) {
	helper := log.NewHelper(logger)
	helper.Infof("data init, driver=%s source=%s", c.Database.GetDriver(), c.Database.GetSource())
	d := &Data{greeters: make(map[string]string)}
	cleanup := func() {
		helper.Info("closing the data resources")
	}
	return d, cleanup, nil
}

package data

import (
	"context"

	"hooo/internal/biz"

	"github.com/go-kratos/kratos/v2/log"
)

type greeterRepo struct {
	data *Data
	log  *log.Helper
}

// NewGreeterRepo 创建 biz.GreeterRepo 的实现。
func NewGreeterRepo(data *Data, logger log.Logger) biz.GreeterRepo {
	return &greeterRepo{data: data, log: log.NewHelper(logger)}
}

// Save 保存问候记录（内存实现）。
func (r *greeterRepo) Save(ctx context.Context, g *biz.Greeter) (*biz.Greeter, error) {
	r.data.mu.Lock()
	defer r.data.mu.Unlock()
	r.data.greeters[g.Name] = g.Message
	r.log.WithContext(ctx).Infof("saved greeter: %s", g.Name)
	return g, nil
}

// Package service 是服务接口层，负责 DTO 与领域对象之间的转换。
package service

import "github.com/google/wire"

// ProviderSet 供 wire 装配本层依赖。
var ProviderSet = wire.NewSet(NewGreeterService)

package service

import (
	"context"

	v1 "hooo/api/helloworld/v1"
	"hooo/internal/biz"
)

// GreeterService 实现 Greeter 的 HTTP API。
type GreeterService struct {
	uc *biz.GreeterUsecase
}

// NewGreeterService 创建服务实例。
func NewGreeterService(uc *biz.GreeterUsecase) *GreeterService {
	return &GreeterService{uc: uc}
}

// SayHello 处理 GET /helloworld/{name}。
func (s *GreeterService) SayHello(ctx context.Context, req *v1.HelloRequest) (*v1.HelloReply, error) {
	g, err := s.uc.CreateGreeter(ctx, &biz.Greeter{Name: req.Name})
	if err != nil {
		return nil, err
	}
	return &v1.HelloReply{Message: g.Message}, nil
}

// Package server 负责创建并配置各协议服务端（HTTP/gRPC）。
package server

import "github.com/google/wire"

// ProviderSet 供 wire 装配本层依赖。
var ProviderSet = wire.NewSet(NewHTTPServer)

package server

import (
	"time"

	v1 "hooo/api/helloworld/v1"
	"hooo/internal/conf"
	"hooo/internal/service"

	"github.com/go-kratos/kratos/v2/log"
	"github.com/go-kratos/kratos/v2/middleware/logging"
	"github.com/go-kratos/kratos/v2/middleware/recovery"
	"github.com/go-kratos/kratos/v2/transport/http"
)

// NewHTTPServer 创建 HTTP 服务端并注册路由。
func NewHTTPServer(c *conf.Server, greeter *service.GreeterService, logger log.Logger) *http.Server {
	opts := []http.ServerOption{
		http.Middleware(
			recovery.Recovery(),
			logging.Server(logger),
		),
	}
	if c.HTTP.Network != "" {
		opts = append(opts, http.Network(c.HTTP.Network))
	}
	if c.HTTP.Addr != "" {
		opts = append(opts, http.Address(c.HTTP.Addr))
	}
	if c.HTTP.Timeout != "" {
		if d, err := time.ParseDuration(c.HTTP.Timeout); err == nil {
			opts = append(opts, http.Timeout(d))
		}
	}
	srv := http.NewServer(opts...)

	// 经典布局中此处调用 proto 生成的 RegisterGreeterHTTPServer(srv, greeter)，
	// 这里手写等价的路由注册。
	r := srv.Route("/")
	r.GET("/helloworld/{name}", func(ctx http.Context) error {
		req := &v1.HelloRequest{Name: ctx.Vars().Get("name")}
		reply, err := greeter.SayHello(ctx, req)
		if err != nil {
			return err
		}
		return ctx.JSON(200, reply)
	})
	return srv
}

package main

import (
	"github.com/go-kratos/kratos/v2"
	"github.com/go-kratos/kratos/v2/log"
	"github.com/go-kratos/kratos/v2/transport/http"
)

// newApp 组装 kratos 应用实例。
func newApp(logger log.Logger, hs *http.Server) *kratos.App {
	return kratos.New(
		kratos.ID(id),
		kratos.Name(Name),
		kratos.Version(Version),
		kratos.Metadata(map[string]string{}),
		kratos.Logger(logger),
		kratos.Server(hs),
	)
}

package main

import (
	"flag"
	"os"

	"hooo/internal/conf"

	"github.com/go-kratos/kratos/v2/config"
	"github.com/go-kratos/kratos/v2/config/file"
	"github.com/go-kratos/kratos/v2/log"
	"github.com/google/uuid"
)

// go build -ldflags "-X main.Version=x.y.z"
var (
	// Name 是应用名称。
	Name = "hooo"
	// Version 是应用版本。
	Version = "v0.1.0"

	id, _ = uuid.NewUUID()

	flagconf string
)

func init() {
	flag.StringVar(&flagconf, "conf", "../../configs", "config path, eg: -conf config.yaml")
}

func main() {
	flag.Parse()
	logger := log.With(log.NewStdLogger(os.Stdout),
		"ts", log.DefaultTimestamp,
		"caller", log.DefaultCaller,
		"service.id", id,
		"service.name", Name,
		"service.version", Version,
	)
	c := config.New(
		config.WithSource(
			file.NewSource(flagconf),
		),
	)
	defer c.Close()

	if err := c.Load(); err != nil {
		panic(err)
	}

	var bc conf.Bootstrap
	if err := c.Scan(&bc); err != nil {
		panic(err)
	}

	app, cleanup, err := wireApp(bc.Server, bc.Data, logger)
	if err != nil {
		panic(err)
	}
	defer cleanup()

	// start and wait for stop signal
	if err := app.Run(); err != nil {
		panic(err)
	}
}

//go:build wireinject
// +build wireinject

// wire 注入声明。运行 `wire ./cmd/hooo` 可重新生成 wire_gen.go。
package main

import (
	"hooo/internal/biz"
	"hooo/internal/conf"
	"hooo/internal/data"
	"hooo/internal/server"
	"hooo/internal/service"

	"github.com/go-kratos/kratos/v2"
	"github.com/go-kratos/kratos/v2/log"
	"github.com/google/wire"
)

// wireApp 声明依赖注入的入口。
func wireApp(*conf.Server, *conf.Data, log.Logger) (*kratos.App, func(), error) {
	panic(wire.Build(server.ProviderSet, data.ProviderSet, biz.ProviderSet, service.ProviderSet, newApp))
}

//go:build !wireinject
// +build !wireinject

package main

import (
	"hooo/internal/biz"
	"hooo/internal/conf"
	"hooo/internal/data"
	"hooo/internal/server"
	"hooo/internal/service"

	"github.com/go-kratos/kratos/v2"
	"github.com/go-kratos/kratos/v2/log"
)

// wireApp 是 wire 生成的依赖装配代码（与 wire.go 中的声明等价）。
func wireApp(confServer *conf.Server, confData *conf.Data, logger log.Logger) (*kratos.App, func(), error) {
	dataData, cleanup, err := data.NewData(confData, logger)
	if err != nil {
		return nil, nil, err
	}
	greeterRepo := data.NewGreeterRepo(dataData, logger)
	greeterUsecase := biz.NewGreeterUsecase(greeterRepo, logger)
	greeterService := service.NewGreeterService(greeterUsecase)
	httpServer := server.NewHTTPServer(confServer, greeterService, logger)
	app := newApp(logger, httpServer)
	return app, func() {
		cleanup()
	}, nil
}

