// Save 保存问候记录（内存实现）。
func (r *greeterRepo) Save(ctx context.Context, g *biz.Greeter) (*biz.Greeter, error) {
	r.data.mu.Lock()
	defer r.data.mu.Unlock()
	r.data.greeters[g.Name] = g.Message
	r.log.WithContext(ctx).Infof("saved greeter: %s", g.Name)
	return g, nil
}

// FindByName 按名称查询，不存在时返回 biz.ErrGreeterNotFound。
func (r *greeterRepo) FindByName(ctx context.Context, name string) (*biz.Greeter, error) {
	r.data.mu.RLock()
	defer r.data.mu.RUnlock()
	msg, ok := r.data.greeters[name]
	if !ok {
		return nil, biz.ErrGreeterNotFound
	}
	return &biz.Greeter{Name: name, Message: msg}, nil
}

// List 列出全部记录，按名称排序保证结果稳定。
func (r *greeterRepo) List(ctx context.Context) ([]*biz.Greeter, error) {
	r.data.mu.RLock()
	defer r.data.mu.RUnlock()
	names := make([]string, 0, len(r.data.greeters))
	for name := range r.data.greeters {
		names = append(names, name)
	}
	sort.Strings(names)
	out := make([]*biz.Greeter, 0, len(names))
	for _, name := range names {
		out = append(out, &biz.Greeter{Name: name, Message: r.data.greeters[name]})
	}
	return out, nil
}

// Delete 删除记录，不存在时返回 biz.ErrGreeterNotFound。
func (r *greeterRepo) Delete(ctx context.Context, name string) error {
	r.data.mu.Lock()
	defer r.data.mu.Unlock()
	if _, ok := r.data.greeters[name]; !ok {
		return biz.ErrGreeterNotFound
	}
	delete(r.data.greeters, name)
	return nil
}

