// CreateGreeter 处理 POST /greeters。
func (s *GreeterService) CreateGreeter(ctx context.Context, req *v1.CreateGreeterRequest) (*v1.GreeterItem, error) {
	g, err := s.uc.CreateGreeter(ctx, &biz.Greeter{Name: req.Name})
	if err != nil {
		return nil, kerrors.BadRequest("INVALID_ARGUMENT", err.Error())
	}
	return &v1.GreeterItem{Name: g.Name, Message: g.Message}, nil
}

// GetGreeter 处理 GET /greeters/{name}。
func (s *GreeterService) GetGreeter(ctx context.Context, req *v1.GetGreeterRequest) (*v1.GreeterItem, error) {
	g, err := s.uc.GetGreeter(ctx, req.Name)
	if err != nil {
		return nil, toKError(err)
	}
	return &v1.GreeterItem{Name: g.Name, Message: g.Message}, nil
}

// ListGreeters 处理 GET /greeters。
func (s *GreeterService) ListGreeters(ctx context.Context) (*v1.ListGreetersReply, error) {
	gs, err := s.uc.ListGreeters(ctx)
	if err != nil {
		return nil, kerrors.InternalServer("INTERNAL", err.Error())
	}
	items := make([]*v1.GreeterItem, 0, len(gs))
	for _, g := range gs {
		items = append(items, &v1.GreeterItem{Name: g.Name, Message: g.Message})
	}
	return &v1.ListGreetersReply{Items: items}, nil
}

// DeleteGreeter 处理 DELETE /greeters/{name}。
func (s *GreeterService) DeleteGreeter(ctx context.Context, req *v1.DeleteGreeterRequest) (*v1.DeleteGreeterReply, error) {
	if err := s.uc.DeleteGreeter(ctx, req.Name); err != nil {
		return nil, toKError(err)
	}
	return &v1.DeleteGreeterReply{Name: req.Name}, nil
}

// toKError 把领域错误映射为 kratos HTTP 错误。
func toKError(err error) error {
	if errors.Is(err, biz.ErrGreeterNotFound) {
