package biz

import (
	"context"
	"errors"
	"testing"

	"github.com/go-kratos/kratos/v2/log"
)

// fakeRepo 是 GreeterRepo 的测试替身。
type fakeRepo struct {
	saved   map[string]*Greeter
	saveErr error
}

func newFakeRepo() *fakeRepo {
	return &fakeRepo{saved: make(map[string]*Greeter)}
}

func (f *fakeRepo) Save(_ context.Context, g *Greeter) (*Greeter, error) {
	if f.saveErr != nil {
		return nil, f.saveErr
	}
	f.saved[g.Name] = g
	return g, nil
}

func (f *fakeRepo) FindByName(_ context.Context, name string) (*Greeter, error) {
	g, ok := f.saved[name]
	if !ok {
		return nil, ErrGreeterNotFound
	}
	return g, nil
}

func (f *fakeRepo) List(_ context.Context) ([]*Greeter, error) {
	out := make([]*Greeter, 0, len(f.saved))
	for _, g := range f.saved {
		out = append(out, g)
	}
	return out, nil
}

func (f *fakeRepo) Delete(_ context.Context, name string) error {
	if _, ok := f.saved[name]; !ok {
		return ErrGreeterNotFound
	}
	delete(f.saved, name)
	return nil
}

func TestCreateGreeter(t *testing.T) {
	repo := newFakeRepo()
	uc := NewGreeterUsecase(repo, log.DefaultLogger)

	g, err := uc.CreateGreeter(context.Background(), &Greeter{Name: "kratos"})
	if err != nil {
		t.Fatalf("CreateGreeter: %v", err)
	}
	if g.Message != "Hello kratos" {
		t.Fatalf("message = %q, want %q", g.Message, "Hello kratos")
	}
	if _, ok := repo.saved["kratos"]; !ok {
		t.Fatal("greeter not saved to repo")
	}
}

func TestCreateGreeterEmptyName(t *testing.T) {
	uc := NewGreeterUsecase(newFakeRepo(), log.DefaultLogger)
	if _, err := uc.CreateGreeter(context.Background(), &Greeter{}); err == nil {
		t.Fatal("expected error for empty name")
	}
}

func TestCreateGreeterRepoError(t *testing.T) {
	repo := newFakeRepo()
	repo.saveErr = errors.New("boom")
	uc := NewGreeterUsecase(repo, log.DefaultLogger)
	if _, err := uc.CreateGreeter(context.Background(), &Greeter{Name: "x"}); err == nil {
		t.Fatal("expected repo error to propagate")
	}
}

func TestGreeterCRUD(t *testing.T) {
	repo := newFakeRepo()
	uc := NewGreeterUsecase(repo, log.DefaultLogger)
	ctx := context.Background()

	if _, err := uc.CreateGreeter(ctx, &Greeter{Name: "a"}); err != nil {
		t.Fatalf("create: %v", err)
	}
	g, err := uc.GetGreeter(ctx, "a")
	if err != nil || g.Name != "a" {
		t.Fatalf("get: g=%v err=%v", g, err)
	}
	if _, err := uc.GetGreeter(ctx, "missing"); !errors.Is(err, ErrGreeterNotFound) {
		t.Fatalf("get missing: err=%v, want ErrGreeterNotFound", err)
	}
	list, err := uc.ListGreeters(ctx)
	if err != nil || len(list) != 1 {
		t.Fatalf("list: n=%d err=%v", len(list), err)
	}
	if err := uc.DeleteGreeter(ctx, "a"); err != nil {
		t.Fatalf("delete: %v", err)
	}
	if err := uc.DeleteGreeter(ctx, "a"); !errors.Is(err, ErrGreeterNotFound) {
		t.Fatalf("delete again: err=%v, want ErrGreeterNotFound", err)
	}
}

