13 │ 	Message string
14 │ }
15 │ 
16 │ // ErrGreeterNotFound 表示问候记录不存在。
17 │ var ErrGreeterNotFound = errors.New("greeter not found")
18 │ 
19 │ // GreeterRepo 是仓储接口，由 data 层实现（依赖倒置）。
20 │ type GreeterRepo interface {
21 │ 	Save(ctx context.Context, g *Greeter) (*Greeter, error)
22 │ 	FindByName(ctx context.Context, name string) (*Greeter, error)
23 │ 	List(ctx context.Context) ([]*Greeter, error)
24 │ 	Delete(ctx context.Context, name string) error
25 │ }
26 │ 
27 │ // GreeterUsecase 是 Greeter 的业务用例。
28 │ type GreeterUsecase struct {
29 │ 	repo GreeterRepo
30 │ 	log  *log.Helper
31 │ }
32 │ 
33 │ // NewGreeterUsecase 创建业务用例。
34 │ func NewGreeterUsecase(repo GreeterRepo, logger log.Logger) *GreeterUsecase {
35 │ 	return &GreeterUsecase{repo: repo, log: log.NewHelper(logger)}
36 │ }
37 │ 
38 │ // CreateGreeter 生成问候语并落库。
39 │ func (uc *GreeterUsecase) CreateGreeter(ctx context.Context, g *Greeter) (*Greeter, error) {
40 │ 	uc.log.WithContext(ctx).Infof("CreateGreeter: %s", g.Name)
41 │ 	if g.Name == "" {
42 │ 		return nil, errors.New("name is required")
43 │ 	}
44 │ 	g.Message = "Hello " + g.Name
45 │ 	return uc.repo.Save(ctx, g)
46 │ }
47 │ 
48 │ // GetGreeter 按名称查询问候记录。
49 │ func (uc *GreeterUsecase) GetGreeter(ctx context.Context, name string) (*Greeter, error) {
50 │ 	return uc.repo.FindByName(ctx, name)
51 │ }
52 │ 
53 │ // ListGreeters 列出全部问候记录。
54 │ func (uc *GreeterUsecase) ListGreeters(ctx context.Context) ([]*Greeter, error) {
55 │ 	return uc.repo.List(ctx)
56 │ }
57 │ 
58 │ // DeleteGreeter 删除问候记录。
