 1 │ package data
 2 │ 
 3 │ import (
 4 │ 	"context"
 5 │ 	"sort"
 6 │ 
 7 │ 	"hooo/internal/biz"
 8 │ 
 9 │ 	"github.com/go-kratos/kratos/v2/log"
10 │ )
11 │ 
12 │ type greeterRepo struct {
13 │ 	data *Data
14 │ 	log  *log.Helper
15 │ }
16 │ 
17 │ // NewGreeterRepo 创建 biz.GreeterRepo 的实现。
18 │ func NewGreeterRepo(data *Data, logger log.Logger) biz.GreeterRepo {
19 │ 	return &greeterRepo{data: data, log: log.NewHelper(logger)}
20 │ }
21 │ 
22 │ // Save 保存问候记录（内存实现）。
23 │ func (r *greeterRepo) Save(ctx context.Context, g *biz.Greeter) (*biz.Greeter, error) {
24 │ 	r.data.mu.Lock()
25 │ 	defer r.data.mu.Unlock()
26 │ 	r.data.greeters[g.Name] = g.Message
27 │ 	r.log.WithContext(ctx).Infof("saved greeter: %s", g.Name)
28 │ 	return g, nil
29 │ }
30 │ 
31 │ // FindByName 按名称查询，不存在时返回 biz.ErrGreeterNotFound。
32 │ func (r *greeterRepo) FindByName(ctx context.Context, name string) (*biz.Greeter, error) {
33 │ 	r.data.mu.RLock()
34 │ 	defer r.data.mu.RUnlock()
35 │ 	msg, ok := r.data.greeters[name]
36 │ 	if !ok {
37 │ 		return nil, biz.ErrGreeterNotFound
38 │ 	}
39 │ 	return &biz.Greeter{Name: name, Message: msg}, nil
40 │ }
41 │ 
42 │ // List 列出全部记录，按名称排序保证结果稳定。
43 │ func (r *greeterRepo) List(ctx context.Context) ([]*biz.Greeter, error) {
44 │ 	r.data.mu.RLock()
45 │ 	defer r.data.mu.RUnlock()
46 │ 	names := make([]string, 0, len(r.data.greeters))
47 │ 	for name := range r.data.greeters {
48 │ 		names = append(names, name)
49 │ 	}
50 │ 	sort.Strings(names)
51 │ 	out := make([]*biz.Greeter, 0, len(names))
52 │ 	for _, name := range names {
53 │ 		out = append(out, &biz.Greeter{Name: name, Message: r.data.greeters[name]})
54 │ 	}
55 │ 	return out, nil
56 │ }
57 │ 
58 │ // Delete 删除记录，不存在时返回 biz.ErrGreeterNotFound。
59 │ func (r *greeterRepo) Delete(ctx context.Context, name string) error {
60 │ 	r.data.mu.Lock()
61 │ 	defer r.data.mu.Unlock()
62 │ 	if _, ok := r.data.greeters[name]; !ok {
63 │ 		return biz.ErrGreeterNotFound
64 │ 	}
65 │ 	delete(r.data.greeters, name)
66 │ 	return nil
67 │ }
