package data

import (
	"context"
	"errors"
	"sync"
	"testing"

	"hooo/internal/biz"
	"hooo/internal/conf"

	"github.com/go-kratos/kratos/v2/log"
)

func newTestRepo(t *testing.T) biz.GreeterRepo {
	t.Helper()
	d, cleanup, err := NewData(&conf.Data{Database: &conf.Database{Driver: "memory", Source: "test"}}, log.DefaultLogger)
	if err != nil {
		t.Fatalf("NewData: %v", err)
	}
	t.Cleanup(cleanup)
	return NewGreeterRepo(d, log.DefaultLogger)
}

func TestRepoSaveAndFind(t *testing.T) {
	repo := newTestRepo(t)
	ctx := context.Background()

	if _, err := repo.Save(ctx, &biz.Greeter{Name: "a", Message: "Hello a"}); err != nil {
		t.Fatalf("save: %v", err)
	}
	g, err := repo.FindByName(ctx, "a")
	if err != nil || g.Message != "Hello a" {
		t.Fatalf("find: g=%v err=%v", g, err)
	}
	if _, err := repo.FindByName(ctx, "missing"); !errors.Is(err, biz.ErrGreeterNotFound) {
		t.Fatalf("find missing: err=%v, want ErrGreeterNotFound", err)
	}
}

func TestRepoListSorted(t *testing.T) {
	repo := newTestRepo(t)
	ctx := context.Background()

	for _, name := range []string{"c", "a", "b"} {
		if _, err := repo.Save(ctx, &biz.Greeter{Name: name, Message: "Hello " + name}); err != nil {
			t.Fatalf("save %s: %v", name, err)
		}
	}
	list, err := repo.List(ctx)
	if err != nil || len(list) != 3 {
		t.Fatalf("list: n=%d err=%v", len(list), err)
	}
	for i, want := range []string{"a", "b", "c"} {
		if list[i].Name != want {
			t.Fatalf("list[%d].Name = %q, want %q", i, list[i].Name, want)
		}
	}
}

func TestRepoDelete(t *testing.T) {
	repo := newTestRepo(t)
	ctx := context.Background()

	if _, err := repo.Save(ctx, &biz.Greeter{Name: "a", Message: "Hello a"}); err != nil {
		t.Fatalf("save: %v", err)
	}
	if err := repo.Delete(ctx, "a"); err != nil {
		t.Fatalf("delete: %v", err)
	}
	if err := repo.Delete(ctx, "a"); !errors.Is(err, biz.ErrGreeterNotFound) {
		t.Fatalf("delete again: err=%v, want ErrGreeterNotFound", err)
	}
}

// TestRepoConcurrent 用 -race 验证内存仓储的并发安全。
func TestRepoConcurrent(t *testing.T) {
	repo := newTestRepo(t)
	ctx := context.Background()

	var wg sync.WaitGroup
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			name := string(rune('a' + i))
			_, _ = repo.Save(ctx, &biz.Greeter{Name: name, Message: "Hello " + name})
			_, _ = repo.FindByName(ctx, name)
			_, _ = repo.List(ctx)
			_ = repo.Delete(ctx, name)
		}(i)
	}
	wg.Wait()
}

package service

import (
	"context"
	"testing"

	v1 "hooo/api/helloworld/v1"
	"hooo/internal/biz"
	"hooo/internal/conf"
	"hooo/internal/data"

	kerrors "github.com/go-kratos/kratos/v2/errors"
	"github.com/go-kratos/kratos/v2/log"
)

// newTestService 用真实的 data 内存仓储装配 service，覆盖整条调用链。
func newTestService(t *testing.T) *GreeterService {
	t.Helper()
	d, cleanup, err := data.NewData(&conf.Data{Database: &conf.Database{Driver: "memory", Source: "test"}}, log.DefaultLogger)
	if err != nil {
		t.Fatalf("NewData: %v", err)
	}
	t.Cleanup(cleanup)
	repo := data.NewGreeterRepo(d, log.DefaultLogger)
	uc := biz.NewGreeterUsecase(repo, log.DefaultLogger)
	return NewGreeterService(uc)
}

func TestSayHello(t *testing.T) {
	s := newTestService(t)
	reply, err := s.SayHello(context.Background(), &v1.HelloRequest{Name: "kratos"})
	if err != nil {
		t.Fatalf("SayHello: %v", err)
	}
	if reply.Message != "Hello kratos" {
		t.Fatalf("message = %q, want %q", reply.Message, "Hello kratos")
	}
}

func TestCreateGreeterInvalidArgument(t *testing.T) {
	s := newTestService(t)
	_, err := s.CreateGreeter(context.Background(), &v1.CreateGreeterRequest{})
	if err == nil {
		t.Fatal("expected error for empty name")
	}
	if kerrors.Code(err) != 400 {
		t.Fatalf("code = %d, want 400", kerrors.Code(err))
	}
}

func TestGreeterCRUDFlow(t *testing.T) {
	s := newTestService(t)
	ctx := context.Background()

	item, err := s.CreateGreeter(ctx, &v1.CreateGreeterRequest{Name: "a"})
	if err != nil || item.Message != "Hello a" {
		t.Fatalf("create: item=%v err=%v", item, err)
	}

	got, err := s.GetGreeter(ctx, &v1.GetGreeterRequest{Name: "a"})
	if err != nil || got.Name != "a" {
		t.Fatalf("get: got=%v err=%v", got, err)
	}

	list, err := s.ListGreeters(ctx)
	if err != nil || len(list.Items) != 1 {
		t.Fatalf("list: n=%d err=%v", len(list.Items), err)
	}

	del, err := s.DeleteGreeter(ctx, &v1.DeleteGreeterRequest{Name: "a"})
	if err != nil || del.Name != "a" {
		t.Fatalf("delete: del=%v err=%v", del, err)
	}
}

func TestGreeterNotFoundMapsTo404(t *testing.T) {
	s := newTestService(t)
	ctx := context.Background()

	if _, err := s.GetGreeter(ctx, &v1.GetGreeterRequest{Name: "missing"}); kerrors.Code(err) != 404 {
		t.Fatalf("get missing: code=%d, want 404", kerrors.Code(err))
	}
	if _, err := s.DeleteGreeter(ctx, &v1.DeleteGreeterRequest{Name: "missing"}); kerrors.Code(err) != 404 {
		t.Fatalf("delete missing: code=%d, want 404", kerrors.Code(err))
	}
}

